PRAGMA foreign_keys=ON;
CREATE TABLE invitations(id INTEGER PRIMARY KEY AUTOINCREMENT,code TEXT NOT NULL UNIQUE COLLATE NOCASE,guest_name TEXT NOT NULL,group_name TEXT,side TEXT CHECK(side IS NULL OR side IN('groom','bride','shared')),max_guests INTEGER CHECK(max_guests IS NULL OR max_guests>=1),is_active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')),updated_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE rsvps(id INTEGER PRIMARY KEY AUTOINCREMENT,invitation_id INTEGER REFERENCES invitations(id) ON DELETE RESTRICT,public_response_token TEXT UNIQUE,guest_name TEXT NOT NULL,attending INTEGER NOT NULL CHECK(attending IN(0,1)),guest_count INTEGER NOT NULL DEFAULT 0 CHECK(guest_count>=0),message TEXT,source TEXT NOT NULL CHECK(source IN('personalized','public')),created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')),updated_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')),CHECK((source='personalized' AND invitation_id IS NOT NULL AND public_response_token IS NULL) OR(source='public' AND invitation_id IS NULL AND public_response_token IS NOT NULL)));
CREATE UNIQUE INDEX ux_rsvp_inv ON rsvps(invitation_id) WHERE invitation_id IS NOT NULL; CREATE INDEX ix_rsvp_source ON rsvps(source,updated_at DESC);
CREATE TABLE wishes(id INTEGER PRIMARY KEY AUTOINCREMENT,invitation_id INTEGER REFERENCES invitations(id) ON DELETE RESTRICT,display_name TEXT NOT NULL,message TEXT NOT NULL,source TEXT NOT NULL CHECK(source IN('personalized','public')),created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now'))); CREATE INDEX ix_wishes_created ON wishes(created_at DESC,id DESC); CREATE INDEX ix_wishes_inv ON wishes(invitation_id,created_at DESC);
CREATE TABLE abuse_counters(bucket TEXT PRIMARY KEY,count INTEGER NOT NULL DEFAULT 0,expires_at INTEGER NOT NULL); CREATE INDEX ix_abuse_exp ON abuse_counters(expires_at);
